function searchkey(query,res){
  connection.query('select * from bi_posts where concat(title,content) like "%'+ connection.escape(query) +'%"', function(err, rows) {
    if(err){ log(err,3);}
    if(rows[0] === undefined){
      res.contentType('application/json');
      res.send('{"error":2}');
      return;
    }


    var result = {
      "error":0,
      "results":{}
    };

    for (var i = 0, len = rows.length; i < len; i++) {
        result['results'][i] = {
            "id":rows[i].id,
            "time":rows[i].time,
            "title":rows[i].title,
            "category":cache.get('categorydata-' + rows[i].category),
            "shortname":rows[i].shortname,
            "content":rows[i].content.replace(/(<([^>]+)>)/ig,"").replace(/\r?\n|\r/g, " ").substr(0,200),
            "firstimg":getFirstImage(rows[i].content)
        }
    }

    if(CACHE_ENABLE == 1){
      cache.put('api-search-' + query, result);
      res.set('X-Builtin-Cache', 'miss');
      cache_miss++;
    }

    res.contentType('application/json');
    res.send(JSON.stringify(result));
  });
}

function compileBlocks(context) {
    var out = [],
        blocks = context.blocks,
        name;

    for (name in blocks) {
      out.push('"' + name + '":' + blocks[name]);
    }
    if (out.length) {
      context.blocks = 'ctx=ctx.shiftBlocks(blocks);';
      return 'var blocks={' + out.join(',') + '};';
    } else {
      context.blocks = '';
    }
    return context.blocks;
  }

function renderConnection(connection, user) {
  const replaced = {};
  Object.keys(connection).forEach((key) => {
    if (key === 'data') {
      const value = renderConnection(connection.data, user);
      connection.data = value;
    } else {
      const value = connection[key];
      if (typeof value === 'string') {
        _.templateSettings.interpolate = /{{([\s\S]+?)}}/g;
        const compiled = _.template(value);
        replaced[key] = compiled({ user });
      } else {
        replaced[key] = value;
      }
    }
  });
  return replaced;
}

