      relative
    && location.slashes
    && url.pathname.charAt(0) !== '/'
    && (url.pathname !== '' || location.pathname !== '')
  ) {
    url.pathname = resolve(url.pathname, location.pathname);
  }

  if (
      url.pathname.charAt(0) !== '/'
    && (url.hostname || url.protocol === 'file:')
  ) {
    url.pathname = '/' + url.pathname;
  }

