function deepExtend (a, b) {
  if (Array.isArray(b)) {
    throw new TypeError('Arrays are not supported by deepExtend')
  }

  for (const prop in b) {
    if (hasOwnProperty(b, prop) && !(prop in Object.prototype) && !(prop in Function.prototype)) {
      if (b[prop] && b[prop].constructor === Object) {
        if (a[prop] === undefined) {
          a[prop] = {}
        }
        if (a[prop] && a[prop].constructor === Object) {
          deepExtend(a[prop], b[prop])
        } else {
          a[prop] = b[prop]
        }
      } else if (Array.isArray(b[prop])) {
        throw new TypeError('Arrays are not supported by deepExtend')
      } else {
        a[prop] = b[prop]
      }
    }
  }
  return a
}

function escapeArgBash(arg, interpolation, quoted) {
  let result = arg.replace(/\0/gu, "");

  if (interpolation) {
    result = result
      .replace(/\\/gu, "\\\\")
      .replace(/\n/gu, " ")
      .replace(/(^|\s)(~|#)/gu, "$1\\$2")
      .replace(/(\*|\?)/gu, "\\$1")
      .replace(/([$&;|])/gu, "\\$1")
      .replace(/([()<>])/gu, "\\$1")
      .replace(/(["'`])/gu, "\\$1")
      .replace(/\{(?=([^,.]*(?:,|\.)[^]*?)\})/gu, "\\{")
      .replace(/(?<==(?:[^]*?:)?)(~)(?=[\s+\-/0:=]|$)/gu, "\\$1");
  } else if (quoted) {
    result = result.replace(/'/gu, `'\\''`);
  }

  return result;
}

